; buffer.asm -- chapter 25: the lines in the RAM, then sent
; generated by gen25.py
        INCLUDE "msx.inc"
        OUTPUT "buffer.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; fan.asm's lines drawn with rline into BUF, 6,144 bytes of the RAM laid out
; as the patterns: cleared first, and sent to the VRAM at the end.
BUF     EQU $C800               ; 6,144 bytes, laid out as the patterns
BUF_H   EQU $C8
togo    EQU VARS                ; the fan's lines left to draw
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the picture is drawn
        VDP_REG 0, $02          ; Graphic II: 256 x 192 pixels (chapter 22)
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000, 6,144 bytes
        VDP_REG 4, $03          ; patterns           $0000, 6,144 bytes
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: every pixel paper
        ld bc, 6144
g2p:    xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2p
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld bc, 6144
g2c:    ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2c
        VRAM_WRITE $1800        ; names: 0 to 255 in each third
        ld b, 3
g2n:    xor a
g2n1:   out (VDP_DATA), a
        inc a
        jr nz, g2n1
        djnz g2n
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VDP_REG 1, $C0          ; the display on: what follows is drawn on it
c0:     call clear
c1:
go:     ld hl, ends             ; the far end of each line: x, then y
        ld a, 88
        ld (togo), a
next:   push hl
        ld b, 128               ; x0
        ld c, 96                ; y0
        ld d, (hl)              ; x1
        inc hl
        ld e, (hl)              ; y1
l0:     call rline
l1:     pop hl
        inc hl
        inc hl
        ld a, (togo)
        dec a
        ld (togo), a
        jr nz, next
s0:     call send
s1:
done:   jr done

; rline: B = x0, C = y0, D = x1, E = y1: the line from (x0, y0) to (x1, y1),
;        every pixel set in the buffer, BUF, which is laid out as the patterns,
;        from its top end down. Uses A, AF', BC, DE, HL.
rline:  ld a, e                 ;  5
        cp c                    ;  5  y1 against y0
        jr nc, rtop             ; 13, or 8
        ld a, b                 ;  5  (x1, y1) is above: the ends change places
        ld b, d                 ;  5
        ld d, a                 ;  5
        ld a, c                 ;  5
        ld c, e                 ;  5
        ld e, a                 ;  5
rtop:   ld a, e                 ;  5
        sub c                   ;  5
        ld e, a                 ;  5  E: dy
        ld a, d                 ;  5
        sub b                   ;  5  x1 - x0
        jp c, rleft             ; 11  to the left
        ld d, a                 ;  5  D: dx
        call rfirst             ; 18  HL: the byte of (x0, y0), C: its mask
        ld a, d                 ;  5
        cp e                    ;  5
        jp c, rsr               ; 11  steeper than 45 degrees
rfr:    ld b, d                 ;  5  flat: dx + 1 pixels
        inc b                   ;  5
        srl a                   ; 10  the error: dx / 2
        ex af, af'              ;  5
rfrpx:  ex af, af'              ;  5  the error,
        sub e                   ;  5  less dy: carry, below zero,
        ex af, af'              ;  5  kept with its carry
        ld a, c                 ;  5  the pixel
        or (hl)                 ;  8  into its byte
        ld (hl), a              ;  8
        rrc c                   ; 10  a pixel right:
        jr nc, rfrsm            ; 13, or 8  in the same byte, or
        ld a, l                 ;  5  in the next, 8 on
        add a, 8                ;  8
        ld l, a                 ;  5
rfrsm:  ex af, af'              ;  5  the error, and its carry
        jr c, rfrdn             ; 13, or 8
        ex af, af'              ;  5
        djnz rfrpx              ; 14, or 9
        ret                     ; 11
rfrdn:  add a, d                ;  5  below zero: dx back,
        ex af, af'              ;  5
        inc l                   ;  5  and a line down (chapter 22's down)
        ld a, l                 ;  5
        and 7                   ;  8
        jr nz, rfrnx            ; 13, or 8
        ld a, l                 ;  5
        sub 8                   ;  8
        ld l, a                 ;  5
        inc h                   ;  5
rfrnx:  djnz rfrpx              ; 14, or 9
        ret                     ; 11
rsr:    ld b, e                 ;  5  steep: dy + 1 pixels
        inc b                   ;  5
        ld a, e                 ;  5
        srl a                   ; 10  the error: dy / 2
        ex af, af'              ;  5
rsrpx:  ex af, af'              ;  5  the error,
        sub d                   ;  5  less dx: carry, below zero,
        ex af, af'              ;  5  kept with its carry
        ld a, c                 ;  5  the pixel
        or (hl)                 ;  8  into its byte
        ld (hl), a              ;  8
        inc l                   ;  5  a line down (chapter 22's down)
        ld a, l                 ;  5
        and 7                   ;  8
        jr nz, rsrsm            ; 13, or 8
        ld a, l                 ;  5
        sub 8                   ;  8
        ld l, a                 ;  5
        inc h                   ;  5
rsrsm:  ex af, af'              ;  5  the error, and its carry
        jr c, rsrdn             ; 13, or 8
        ex af, af'              ;  5
        djnz rsrpx              ; 14, or 9
        ret                     ; 11
rsrdn:  add a, e                ;  5  below zero: dy back,
        ex af, af'              ;  5
        rrc c                   ; 10  and a pixel right:
        jr nc, rsrnx            ; 13, or 8  in the same byte, or
        ld a, l                 ;  5  in the next, 8 on
        add a, 8                ;  8
        ld l, a                 ;  5
rsrnx:  djnz rsrpx              ; 14, or 9
        ret                     ; 11
rleft:  neg                     ; 10  to the left: dx = x0 - x1
        ld d, a                 ;  5  D: dx
        call rfirst             ; 18
        ld a, d                 ;  5
        cp e                    ;  5
        jp c, rsl               ; 11
rfl:    ld b, d                 ;  5  flat: dx + 1 pixels
        inc b                   ;  5
        srl a                   ; 10  the error: dx / 2
        ex af, af'              ;  5
rflpx:  ex af, af'              ;  5  the error,
        sub e                   ;  5  less dy: carry, below zero,
        ex af, af'              ;  5  kept with its carry
        ld a, c                 ;  5  the pixel
        or (hl)                 ;  8  into its byte
        ld (hl), a              ;  8
        rlc c                   ; 10  a pixel left:
        jr nc, rflsm            ; 13, or 8  in the same byte, or
        ld a, l                 ;  5  in the next, 8 back
        sub 8                   ;  8
        ld l, a                 ;  5
rflsm:  ex af, af'              ;  5  the error, and its carry
        jr c, rfldn             ; 13, or 8
        ex af, af'              ;  5
        djnz rflpx              ; 14, or 9
        ret                     ; 11
rfldn:  add a, d                ;  5  below zero: dx back,
        ex af, af'              ;  5
        inc l                   ;  5  and a line down (chapter 22's down)
        ld a, l                 ;  5
        and 7                   ;  8
        jr nz, rflnx            ; 13, or 8
        ld a, l                 ;  5
        sub 8                   ;  8
        ld l, a                 ;  5
        inc h                   ;  5
rflnx:  djnz rflpx              ; 14, or 9
        ret                     ; 11
rsl:    ld b, e                 ;  5  steep: dy + 1 pixels
        inc b                   ;  5
        ld a, e                 ;  5
        srl a                   ; 10  the error: dy / 2
        ex af, af'              ;  5
rslpx:  ex af, af'              ;  5  the error,
        sub d                   ;  5  less dx: carry, below zero,
        ex af, af'              ;  5  kept with its carry
        ld a, c                 ;  5  the pixel
        or (hl)                 ;  8  into its byte
        ld (hl), a              ;  8
        inc l                   ;  5  a line down (chapter 22's down)
        ld a, l                 ;  5
        and 7                   ;  8
        jr nz, rslsm            ; 13, or 8
        ld a, l                 ;  5
        sub 8                   ;  8
        ld l, a                 ;  5
        inc h                   ;  5
rslsm:  ex af, af'              ;  5  the error, and its carry
        jr c, rsldn             ; 13, or 8
        ex af, af'              ;  5
        djnz rslpx              ; 14, or 9
        ret                     ; 11
rsldn:  add a, e                ;  5  below zero: dy back,
        ex af, af'              ;  5
        rlc c                   ; 10  and a pixel left:
        jr nc, rslnx            ; 13, or 8  in the same byte, or
        ld a, l                 ;  5  in the next, 8 back
        sub 8                   ;  8
        ld l, a                 ;  5
rslnx:  djnz rslpx              ; 14, or 9
        ret                     ; 11

; rfirst: B = x, C = y -> HL: the byte of pixel (x, y), C: its mask
rfirst: call vaddr              ; 18
        ld a, h                 ;  5  in the buffer
        add a, BUF_H            ;  8
        ld h, a                 ;  5
        ld a, b                 ;  5
        and 7                   ;  8
        ld c, a                 ;  5
        ld b, high masks        ;  8
        ld a, (bc)              ;  8
        ld c, a                 ;  5
        ret                     ; 11

; clear: the 6,144 bytes of the buffer set to 0
clear:  ld hl, BUF              ; 11
        ld de, BUF + 1          ; 11
        ld bc, 6143             ; 11
        ld (hl), 0              ; 11
        ldir                    ; 23 a byte, 18 the last
        ret                     ; 11

; send: the buffer to the patterns, 29 T-states a byte (chapter 20)
send:   VRAM_WRITE $0000        ; 34  the patterns
        ld hl, BUF              ; 11
        ld c, VDP_DATA          ;  8
        ld d, 24                ;  8  24 x 256 bytes
sendp:  ld b, 0                 ;  8
sendb:  outi                    ; 18
        jp nz, sendb            ; 11
        dec d                   ;  5
        jr nz, sendp            ; 13, or 8
        ret                     ; 11

; vaddr: B = x, C = y -> HL = the address of the byte that holds pixel (x, y),
; in the patterns of a Graphic II screen whose names run 0 to 255 in each
; third (chapter 22). Uses A.
vaddr:  ld a, c                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and $1F                 ;  8: y / 8, the row of characters
        ld h, a                 ;  5
        ld a, b                 ;  5
        and $F8                 ;  8: the column of characters, x 8
        ld l, a                 ;  5
        ld a, c                 ;  5
        and 7                   ;  8: the line in the cell
        or l                    ;  5
        ld l, a                 ;  5
        ret                     ; 11
ends:
        db 40, 8
        db 48, 8
        db 56, 8
        db 64, 8
        db 72, 8
        db 80, 8
        db 88, 8
        db 96, 8
        db 104, 8
        db 112, 8
        db 120, 8
        db 128, 8
        db 136, 8
        db 144, 8
        db 152, 8
        db 160, 8
        db 168, 8
        db 176, 8
        db 184, 8
        db 192, 8
        db 200, 8
        db 208, 8
        db 216, 8
        db 216, 16
        db 216, 24
        db 216, 32
        db 216, 40
        db 216, 48
        db 216, 56
        db 216, 64
        db 216, 72
        db 216, 80
        db 216, 88
        db 216, 96
        db 216, 104
        db 216, 112
        db 216, 120
        db 216, 128
        db 216, 136
        db 216, 144
        db 216, 152
        db 216, 160
        db 216, 168
        db 216, 176
        db 216, 184
        db 208, 184
        db 200, 184
        db 192, 184
        db 184, 184
        db 176, 184
        db 168, 184
        db 160, 184
        db 152, 184
        db 144, 184
        db 136, 184
        db 128, 184
        db 120, 184
        db 112, 184
        db 104, 184
        db 96, 184
        db 88, 184
        db 80, 184
        db 72, 184
        db 64, 184
        db 56, 184
        db 48, 184
        db 40, 184
        db 40, 176
        db 40, 168
        db 40, 160
        db 40, 152
        db 40, 144
        db 40, 136
        db 40, 128
        db 40, 120
        db 40, 112
        db 40, 104
        db 40, 96
        db 40, 88
        db 40, 80
        db 40, 72
        db 40, 64
        db 40, 56
        db 40, 48
        db 40, 40
        db 40, 32
        db 40, 24
        db 40, 16

        ALIGN 256
masks:  db $80, $40, $20, $10, $08, $04, $02, $01 ; pixel n of a byte: bit 7 - n
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
